using System.Globalization; using DataMaker.Refactored.Expressions; using DataMaker.Refactored.Models;
namespace DataMaker.Refactored.Generators;
public sealed class GenerationContext { public Dictionary<string,long> Variables { get; } = new(); }
public sealed record GeneratedEdge(int U,int V,long Weight=0);
public sealed class GeneratorService
{
 public string Generate(ProjectConfig config,int testPoint,int seed){var random=new Random(seed);var groups=config.Groups.FirstOrDefault(x=>testPoint>=x.From&&testPoint<=x.To);var context=new GenerationContext();var lines=new List<string>();foreach(var field in config.Fields){lines.Add(GenerateField(field,groups,context,random));}return string.Join(Environment.NewLine,lines)+Environment.NewLine;}
 string GenerateField(FieldConfig field,GroupConfig? group,GenerationContext ctx,Random random){return field switch {IntField x=>Int(x,group,ctx,random),FloatField x=>Float(x,group,ctx,random),StringField x=>String(x,group,ctx,random),ArrayField x=>Array(x,group,ctx,random),TreeField x=>Tree(x,group,ctx,random),GraphField x=>Graph(x,group,ctx,random),_=>throw new NotSupportedException(field.GetType().Name)};}
 string Int(IntField f,GroupConfig? g,GenerationContext c,Random r){var o=Typed<IntegerFieldOverride>(g,f.Name);var min=Eval(o?.Min??f.Min,c);var max=Eval(o?.Max??f.Max,c);if(max<min)throw new ExpressionException($"字段 {f.Name} 范围无效");var value=min+r.NextInt64(max-min+1);c.Variables[f.Name]=value;return value.ToString();}
 string Float(FloatField f,GroupConfig? g,GenerationContext c,Random r){var o=Typed<FloatFieldOverride>(g,f.Name);var min=EvalD(o?.Min??f.Min,c);var max=EvalD(o?.Max??f.Max,c);var precision=o?.Precision??f.Precision;if(max<min)throw new ExpressionException($"字段 {f.Name} 范围无效");if(!double.IsFinite(min)||!double.IsFinite(max))throw new ExpressionException($"字段 {f.Name} 范围不是有效数值");var value=min+r.NextDouble()*(max-min);c.Variables[f.Name]=(long)value;return value.ToString($"F{Math.Clamp(precision,0,15)}",CultureInfo.InvariantCulture);}
 string String(StringField f,GroupConfig? g,GenerationContext c,Random r){var o=Typed<StringFieldOverride>(g,f.Name);var minLengthText=o?.MinLength??f.MinLength;var maxLengthText=o?.MaxLength??f.MaxLength;var minLength=minLengthText is null?null:(int?)EvalInt(minLengthText,c);var maxLength=maxLengthText is null?null:(int?)EvalInt(maxLengthText,c);if(minLength is<0)throw new ExpressionException($"字段 {f.Name} 的最小长度不能为负数");if(maxLength is<0)throw new ExpressionException($"字段 {f.Name} 的最大长度不能为负数");if(minLength.HasValue&&maxLength.HasValue&&maxLength<minLength)throw new ExpressionException($"字段 {f.Name} 长度范围无效");var n=minLength.HasValue&&maxLength.HasValue?r.Next(minLength.Value,maxLength.Value+1):(int)EvalInt(o?.Length??f.Length,c);if(n<0)throw new ExpressionException($"字段 {f.Name} 的长度不能为负数");var preset=o?.CharsetPreset??f.CharsetPreset;var charset=o?.CustomCharset??f.Charset;var pattern=o?.Pattern??f.Pattern;var chars=ResolveCharset(preset,charset);if(chars.Length==0)throw new ExpressionException($"字段 {f.Name} 的字符集为空");var s=new string(Enumerable.Range(0,n).Select(_=>chars[r.Next(chars.Length)]).ToArray());if(pattern==StringPattern.Periodic&&n>0){var period=r.Next(1,n+1);s=new string(Enumerable.Range(0,n).Select(i=>s[i%period]).ToArray());}return pattern switch{StringPattern.Same=>new string(s[0],n),StringPattern.Palindrome=>MakePalindrome(s),_=>s};}
 string Array(ArrayField f,GroupConfig? g,GenerationContext c,Random r){var o=Typed<ArrayFieldOverride>(g,f.Name);var length=o?.Length??f.Length;var minText=o?.Min??f.Min;var maxText=o?.Max??f.Max;var n=(int)EvalInt(length,c);if(n<0)throw new ExpressionException($"字段 {f.Name} 的数组长度不能为负数");var precision=o?.Precision??f.Precision;var separator=(o?.Separator??f.Separator)==ArraySeparator.NewLine?Environment.NewLine:" ";if(f.ElementType==ArrayElementType.Float){var fmin=EvalD(minText,c);var fmax=EvalD(maxText,c);if(fmax<fmin)throw new ExpressionException($"字段 {f.Name} 范围无效");return string.Join(separator,Enumerable.Range(0,n).Select(_=>(fmin+r.NextDouble()*(fmax-fmin)).ToString($"F{Math.Clamp(precision,0,15)}",CultureInfo.InvariantCulture)));}if(f.ElementType==ArrayElementType.String){var stringMin=o?.StringMinLength??f.StringMinLength;var stringMax=o?.StringMaxLength??f.StringMaxLength;var items=Enumerable.Range(0,n).Select(_=>{var sf=new StringField{Length=stringMax,MinLength=stringMin,MaxLength=stringMax,Charset=f.Charset,CharsetPreset=f.CharsetPreset,Pattern=StringPattern.Random};return String(sf,null,c,r);});return string.Join(separator,items);}var min=EvalInt(minText,c);var max=EvalInt(maxText,c);if(max<min)throw new ExpressionException($"字段 {f.Name} 范围无效");var values=Enumerable.Range(0,n).Select(_=>min+r.NextInt64(Math.Max(1,max-min+1))).ToList();var unique=o?.Unique??f.Unique;var sort=o?.SortOrder??f.SortOrder;var pattern=o?.Pattern??f.Pattern;if(pattern==ArrayPattern.Same)return string.Join(separator,Enumerable.Repeat(min,n));if(unique){if(max-min+1<n)throw new ExpressionException($"字段 {f.Name} 去重范围不足");values=values.Distinct().ToList();while(values.Count<n){var v=min+r.NextInt64(max-min+1);if(!values.Contains(v))values.Add(v);}}if(pattern==ArrayPattern.StrictIncreasing){values=values.Distinct().OrderBy(x=>x).ToList();}else if(pattern==ArrayPattern.NonDecreasing){values.Sort();}else if(pattern==ArrayPattern.StrictDecreasing){values=values.Distinct().OrderByDescending(x=>x).ToList();}else if(pattern==ArrayPattern.NonIncreasing){values.Sort();values.Reverse();}if(values.Count!=n)throw new ExpressionException($"字段 {f.Name} 的数组范围不足以满足特殊性质");if(sort==ArraySortOrder.Ascending)values.Sort();if(sort==ArraySortOrder.Descending){values.Sort();values.Reverse();}return string.Join(separator,values);}
 string Tree(TreeField f,GroupConfig? g,GenerationContext c,Random r){var o=Typed<TreeFieldOverride>(g,f.Name);var n=(int)EvalInt(o?.Nodes??f.Nodes,c);if(n<1)throw new ExpressionException("树节点数必须大于 0");var first=f.IndexStart;var last=first+n-1;var root=o?.Root??f.Root;var shape=o?.Shape??f.Shape;if(root<first||root>last)throw new ExpressionException($"树根节点必须在 {first} 到 {last} 范围内");var nodes=Enumerable.Range(first,n).Where(x=>x!=root).ToList();var min=EvalInt(o?.WeightMin??f.WeightMin,c);var max=EvalInt(o?.WeightMax??f.WeightMax,c);if(max<min)throw new ExpressionException($"字段 {f.Name} 边权范围无效");var edges=new List<GeneratedEdge>();var available=new List<int>{root};var childCount=new Dictionary<int,int>{{root,0}};for(var i=0;i<nodes.Count;i++){var v=nodes[i];var parent=shape switch{TreeShape.Star=>root,TreeShape.Chain=>i==0?root:nodes[i-1],TreeShape.Binary=>available.Count>0?available[0]:root,_=>v>first?r.Next(first,v):root};edges.Add(new(parent,v,f.Weighted?min+r.NextInt64(Math.Max(1,max-min+1)):0));if(shape==TreeShape.Binary){childCount[parent]++;available.Add(v);childCount[v]=0;if(childCount[parent]>=2)available.Remove(parent);}}return string.Join("\n",edges.Select(e=>f.Weighted?$"{e.U} {e.V} {e.Weight}":$"{e.U} {e.V}"));}
 string Graph(GraphField f,GroupConfig? g,GenerationContext c,Random r){var o=Typed<GraphFieldOverride>(g,f.Name);var n=(int)EvalInt(o?.VertexCount??f.Nodes,c);var m=(int)EvalInt(o?.EdgeCount??f.Edges,c);if(n<1)throw new ExpressionException($"字段 {f.Name} 的节点数必须大于 0");if(m<0)throw new ExpressionException($"字段 {f.Name} 的边数不能为负数");var first=f.IndexStart;var last=first+n-1;if(f.Dag&&f.AllowSelfLoops)throw new ExpressionException("DAG 不能允许自环");var wmin=EvalInt(o?.WeightMin??f.WeightMin,c);var wmax=EvalInt(o?.WeightMax??f.WeightMax,c);if(wmax<wmin)throw new ExpressionException($"字段 {f.Name} 边权范围无效");var set=new HashSet<(int,int)>();var edges=new List<GeneratedEdge>();void Add(int u,int v){if(!f.AllowSelfLoops&&u==v)return;if(f.Dag&&u>=v)return;if(f.Bipartite){var leftCount=f.LeftPartSize>0?f.LeftPartSize:n/2;var leftEnd=first+leftCount-1;if((u<=leftEnd)==(v<=leftEnd))return;}var key=f.Directed?(u,v):(Math.Min(u,v),Math.Max(u,v));if(!f.AllowMultiEdges&&!set.Add(key))return;edges.Add(new(u,v,f.Weighted?wmin+r.NextInt64(Math.Max(1,wmax-wmin+1)):0));}var shape=o?.SpecialType??f.Shape;var density=o?.Density??f.Density;if((shape==GraphSpecialType.Sparse||shape==GraphSpecialType.Dense)&&density>=0&&density<=1){var maxEdges=f.Directed?n*(n-1):n*(n-1)/2;m=(int)Math.Clamp(Math.Round(maxEdges*(shape==GraphSpecialType.Sparse?Math.Min(density,0.2):Math.Max(density,0.8))),0,maxEdges);}if(shape==GraphSpecialType.Chain)for(var v=first+1;v<=last&&edges.Count<m;v++)Add(v-1,v);else if(shape==GraphSpecialType.Flower)for(var v=first+1;v<=last&&edges.Count<m;v++)Add(first,v);else if(shape==GraphSpecialType.BinaryTree)for(var v=first+1;v<=last&&edges.Count<m;v++){var logical=v-first;Add(first+(logical-1)/2,v);}else if(shape==GraphSpecialType.Grid){var width=Math.Max(1,(int)Math.Sqrt(n));for(var v=first;v<=last&&edges.Count<m;v++){var p=v-first;if(p%width<width-1&&v<last)Add(v,v+1);if(p+width<n&&edges.Count<m)Add(v,v+width);}}else if(f.Connected)for(var v=first+1;v<=last&&edges.Count<m;v++)Add(r.Next(first,v),v);for(var i=0;i<m*100+1000&&edges.Count<m;i++){var u=r.Next(first,last+1);var v=r.Next(first,last+1);if(f.Dag&&u>v)(u,v)=(v,u);Add(u,v);}if(edges.Count<m)throw new ExpressionException("无法按当前约束生成足够的边");return string.Join("\n",edges.Select(e=>f.Weighted?$"{e.U} {e.V} {e.Weight}":$"{e.U} {e.V}"));}
 static string ResolveCharset(CharsetPreset preset,string manual){if(!string.IsNullOrEmpty(manual))return manual;return preset switch{CharsetPreset.Digits=>"0123456789",CharsetPreset.Lowercase=>"abcdefghijklmnopqrstuvwxyz",CharsetPreset.Uppercase=>"ABCDEFGHIJKLMNOPQRSTUVWXYZ",CharsetPreset.Letters=>"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ",CharsetPreset.DigitsAndLetters=>"0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ",_=>""};}
 long Eval(string value,GenerationContext c)=>ExpressionEvaluator.EvaluateInt(value,c.Variables);double EvalD(string value,GenerationContext c)=>ExpressionEvaluator.Evaluate(value,c.Variables);long EvalInt(string value,GenerationContext c)=>ExpressionEvaluator.EvaluateInt(value,c.Variables);static T? Typed<T>(GroupConfig? g,string field) where T:FieldOverrideBase=>g?.TypedOverrides.TryGetValue(field,out var value)==true?value as T:null;static string MakePalindrome(string s){var h=s[..((s.Length+1)/2)];return h+new string(h.Reverse().Skip(s.Length%2).ToArray());}
}
